<section class="panel form-panel"><h2>Información para tomar decisiones</h2><form class="filters"><?php choose('type','Reporte',['patients'=>'Pacientes registrados','appointments'=>'Citas por estado','no_show'=>'Inasistencias','treatments'=>'Tratamientos realizados','income'=>'Ingresos registrados','balances'=>'Saldos de planes creados en el período','inventory'=>'Consumo y movimientos de inventario'],$type); field('from','Desde',$from,'date'); field('to','Hasta',$to,'date'); ?><button class="button">Consultar</button></form><p class="muted">Período inclusivo en hora local. Los saldos reflejan cobros vigentes al momento de consultar.</p></section>
<section class="panel"><div class="panel-heading"><h2>Resultado del reporte</h2><div class="actions"><?php foreach(['csv','pdf'] as $format): ?><a class="button secondary small" href="<?= e(url('/admin/reports?'.http_build_query(compact('type','from','to')+['export'=>$format]))) ?>">Exportar <?= strtoupper($format) ?></a><?php endforeach; ?></div></div><?php if($type==='appointments' && $report['rows']): ?><canvas id="report-chart" height="180" role="img" aria-label="Cantidad de citas por estado" data-chart="<?= e(json_encode($report['rows'])) ?>"></canvas><?php endif; ?><div class="table-wrap" tabindex="0" role="region" aria-label="Tabla de registros"><table><thead><tr><?php foreach($report['columns'] as $c): ?><th><?= e($c) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($report['rows'] as $r): ?><tr><?php foreach($r as $v): ?><td><?= e(label((string)$v)) ?></td><?php endforeach; ?></tr><?php endforeach; ?><?php if(!$report['rows']): ?><tr><td colspan="<?= count($report['columns']) ?>" class="empty">No hay registros en este período.</td></tr><?php endif; ?></tbody></table></div></section>
